const recordRolloutCheck = `-- name: RecordRolloutCheck :exec
UPDATE rollouts SET last_check = $2, last_check_at = $3 WHERE id = $1
`

type RecordRolloutCheckParams struct {
	ID          pgtype.UUID
	LastCheck   []byte
	LastCheckAt pgtype.Timestamptz
}

func (q *Queries) RecordRolloutCheck(ctx context.Context, arg RecordRolloutCheckParams) error {
	_, err := q.db.Exec(ctx, recordRolloutCheck, arg.ID, arg.LastCheck, arg.LastCheckAt)
	return err
}

const setRolloutState = `-- name: SetRolloutState :one
UPDATE rollouts
   SET state = $1, state_reason = $2,
       stage_started_at = COALESCE($3::timestamptz, stage_started_at),
       updated_at = $4
 WHERE id = $5 AND state = ANY($6::text[])
 RETURNING id, organization_id, app_id, environment_id, channel_id, environment_key, channel_key, candidate_sequence, previous_sequence, salt, state, close_action, close_state, stages, stage_index, stage_started_at, basis_points, start_at, end_at, targeting, allow_devices, deny_devices, health, state_reason, last_check, last_check_at, reverted_sequence, created_by, created_at, updated_at
`

type SetRolloutStateParams struct {
	State          string
	Reason         string
	StageStartedAt pgtype.Timestamptz
	At             pgtype.Timestamptz
	ID             pgtype.UUID
	FromStates     []string
}

// Pauses or resumes a rollout. A resumed rollout starts its stage afresh.
func (q *Queries) SetRolloutState(ctx context.Context, arg SetRolloutStateParams) (Rollout, error) {
	row := q.db.QueryRow(ctx, setRolloutState,
		arg.State,
		arg.Reason,
		arg.StageStartedAt,
		arg.At,
		arg.ID,
		arg.FromStates,
	)
	var i Rollout
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.AppID,
		&i.EnvironmentID,
		&i.ChannelID,
		&i.EnvironmentKey,
		&i.ChannelKey,
		&i.CandidateSequence,
		&i.PreviousSequence,
		&i.Salt,
		&i.State,
		&i.CloseAction,
		&i.CloseState,
		&i.Stages,
		&i.StageIndex,
		&i.StageStartedAt,
		&i.BasisPoints,
		&i.StartAt,
		&i.EndAt,
		&i.Targeting,
		&i.AllowDevices,
		&i.DenyDevices,
		&i.Health,
		&i.StateReason,
		&i.LastCheck,
		&i.LastCheckAt,
		&i.RevertedSequence,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const startRollout = `-- name: StartRollout :one
UPDATE rollouts
   SET state = 'active', previous_sequence = $2, stage_index = 0, stage_started_at = $3, basis_points = $4,
       state_reason = '', updated_at = $3
 WHERE id = $1 AND state = 'scheduled'
 RETURNING id, organization_id, app_id, environment_id, channel_id, environment_key, channel_key, candidate_sequence, previous_sequence, salt, state, close_action, close_state, stages, stage_index, stage_started_at, basis_points, start_at, end_at, targeting, allow_devices, deny_devices, health, state_reason, last_check, last_check_at, reverted_sequence, created_by, created_at, updated_at
`

type StartRolloutParams struct {
	ID               pgtype.UUID
	PreviousSequence *int64
	StageStartedAt   pgtype.Timestamptz
	BasisPoints      int32
}

// Moves a scheduled rollout to its first stage; only one caller wins.
func (q *Queries) StartRollout(ctx context.Context, arg StartRolloutParams) (Rollout, error) {
	row := q.db.QueryRow(ctx, startRollout,
		arg.ID,
		arg.PreviousSequence,
		arg.StageStartedAt,
		arg.BasisPoints,
	)
	var i Rollout
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.AppID,
		&i.EnvironmentID,
		&i.ChannelID,
		&i.EnvironmentKey,
		&i.ChannelKey,
		&i.CandidateSequence,
		&i.PreviousSequence,
		&i.Salt,
		&i.State,
		&i.CloseAction,
		&i.CloseState,
		&i.Stages,
		&i.StageIndex,
		&i.StageStartedAt,
		&i.BasisPoints,
		&i.StartAt,
		&i.EndAt,
		&i.Targeting,
		&i.AllowDevices,
		&i.DenyDevices,
		&i.Health,
		&i.StateReason,
		&i.LastCheck,
		&i.LastCheckAt,
		&i.RevertedSequence,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
